"""URL shortener REST API."""
import secrets
import sqlite3
import string
from urllib.parse import urlparse

from flask import Flask, g, jsonify, redirect, request

ALPHABET = string.ascii_letters + string.digits
CODE_LENGTH = 7

SCHEMA = """
CREATE TABLE IF NOT EXISTS urls (
    code TEXT PRIMARY KEY,
    url TEXT NOT NULL,
    clicks INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_urls_url ON urls(url);
"""


def create_app(db_path="urls.db"):
    app = Flask(__name__)
    app.config["DB_PATH"] = db_path

    def get_db():
        if "db" not in g:
            g.db = sqlite3.connect(app.config["DB_PATH"])
            g.db.row_factory = sqlite3.Row
        return g.db

    @app.teardown_appcontext
    def close_db(_exc):
        db = g.pop("db", None)
        if db is not None:
            db.close()

    with sqlite3.connect(db_path) as conn:
        conn.executescript(SCHEMA)

    def generate_code(db):
        while True:
            code = "".join(secrets.choice(ALPHABET) for _ in range(CODE_LENGTH))
            if not db.execute("SELECT 1 FROM urls WHERE code = ?", (code,)).fetchone():
                return code

    def valid_url(url):
        try:
            parts = urlparse(url)
            return parts.scheme in ("http", "https") and bool(parts.netloc)
        except ValueError:
            return False

    @app.post("/api/shorten")
    def shorten():
        data = request.get_json(silent=True) or {}
        url = data.get("url", "").strip()
        if not url:
            return jsonify(error="'url' is required"), 400
        if not valid_url(url):
            return jsonify(error="invalid URL; must be http(s) with a host"), 400

        db = get_db()
        custom = data.get("code")
        if custom is not None:
            if not (1 <= len(custom) <= 32 and all(c in ALPHABET for c in custom)):
                return jsonify(error="code must be 1-32 alphanumeric characters"), 400
            if db.execute("SELECT 1 FROM urls WHERE code = ?", (custom,)).fetchone():
                return jsonify(error="code already in use"), 409
            code = custom
        else:
            row = db.execute("SELECT code FROM urls WHERE url = ?", (url,)).fetchone()
            if row:
                return jsonify(code=row["code"], url=url,
                               short_url=request.host_url + row["code"]), 200
            code = generate_code(db)

        db.execute("INSERT INTO urls (code, url) VALUES (?, ?)", (code, url))
        db.commit()
        return jsonify(code=code, url=url, short_url=request.host_url + code), 201

    @app.get("/<code>")
    def follow(code):
        db = get_db()
        row = db.execute("SELECT url FROM urls WHERE code = ?", (code,)).fetchone()
        if row is None:
            return jsonify(error="not found"), 404
        db.execute("UPDATE urls SET clicks = clicks + 1 WHERE code = ?", (code,))
        db.commit()
        return redirect(row["url"], code=302)

    @app.get("/api/stats/<code>")
    def stats(code):
        row = get_db().execute(
            "SELECT code, url, clicks, created_at FROM urls WHERE code = ?", (code,)
        ).fetchone()
        if row is None:
            return jsonify(error="not found"), 404
        return jsonify(dict(row))

    @app.delete("/api/urls/<code>")
    def delete(code):
        db = get_db()
        cur = db.execute("DELETE FROM urls WHERE code = ?", (code,))
        db.commit()
        if cur.rowcount == 0:
            return jsonify(error="not found"), 404
        return "", 204

    return app


if __name__ == "__main__":
    create_app().run(debug=True)

import pytest

from app import create_app


@pytest.fixture
def client(tmp_path):
    app = create_app(db_path=str(tmp_path / "test.db"))
    app.config["TESTING"] = True
    with app.test_client() as c:
        yield c


def shorten(client, url="https://example.com/page", **extra):
    return client.post("/api/shorten", json={"url": url, **extra})


class TestShorten:
    def test_creates_short_url(self, client):
        res = shorten(client)
        assert res.status_code == 201
        body = res.get_json()
        assert body["url"] == "https://example.com/page"
        assert len(body["code"]) == 7
        assert body["short_url"].endswith(body["code"])

    def test_same_url_returns_existing_code(self, client):
        first = shorten(client).get_json()
        res = shorten(client)
        assert res.status_code == 200
        assert res.get_json()["code"] == first["code"]

    def test_custom_code(self, client):
        res = shorten(client, code="mycode")
        assert res.status_code == 201
        assert res.get_json()["code"] == "mycode"

    def test_custom_code_conflict(self, client):
        shorten(client, code="taken")
        res = shorten(client, url="https://other.com", code="taken")
        assert res.status_code == 409

    @pytest.mark.parametrize("code", ["", "has space", "a" * 33, "bad/char"])
    def test_invalid_custom_code(self, client, code):
        assert shorten(client, code=code).status_code == 400

    @pytest.mark.parametrize("url", ["", "notaurl", "ftp://x.com", "http://"])
    def test_invalid_url(self, client, url):
        assert shorten(client, url=url).status_code == 400

    def test_missing_body(self, client):
        assert client.post("/api/shorten").status_code == 400


class TestRedirect:
    def test_redirects(self, client):
        code = shorten(client).get_json()["code"]
        res = client.get(f"/{code}")
        assert res.status_code == 302
        assert res.headers["Location"] == "https://example.com/page"

    def test_unknown_code_404(self, client):
        assert client.get("/nope123").status_code == 404


class TestStats:
    def test_counts_clicks(self, client):
        code = shorten(client).get_json()["code"]
        for _ in range(3):
            client.get(f"/{code}")
        body = client.get(f"/api/stats/{code}").get_json()
        assert body["clicks"] == 3
        assert body["url"] == "https://example.com/page"
        assert body["created_at"]

    def test_unknown_code_404(self, client):
        assert client.get("/api/stats/nope123").status_code == 404


class TestDelete:
    def test_delete_then_404(self, client):
        code = shorten(client).get_json()["code"]
        assert client.delete(f"/api/urls/{code}").status_code == 204
        assert client.get(f"/{code}").status_code == 404

    def test_delete_unknown_404(self, client):
        assert client.delete("/api/urls/nope123").status_code == 404

